import{_ as a,o as r,c as e,ag as i}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"量子计算前沿进展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/quantum-computing-progress.md","filePath":"topics/physics/quantum-computing-progress.md"}'),o={name:"topics/physics/quantum-computing-progress.md"};function l(n,t,d,s,h,u){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="量子计算前沿进展" tabindex="-1">量子计算前沿进展 <a class="header-anchor" href="#量子计算前沿进展" aria-label="Permalink to &quot;量子计算前沿进展&quot;">​</a></h1><blockquote><p>持续追踪量子计算、量子模拟、量子传感等领域突破。</p></blockquote><hr><h2 id="_2026年6月-量子纠错800倍突破" tabindex="-1">2026年6月：量子纠错800倍突破 <a class="header-anchor" href="#_2026年6月-量子纠错800倍突破" aria-label="Permalink to &quot;2026年6月：量子纠错800倍突破&quot;">​</a></h2><h3 id="微软-×-quantinuum-《自然》-6月10日" tabindex="-1">微软 × Quantinuum（《自然》，6月10日） <a class="header-anchor" href="#微软-×-quantinuum-《自然》-6月10日" aria-label="Permalink to &quot;微软 × Quantinuum（《自然》，6月10日）&quot;">​</a></h3><p>基于离子阱量子电荷耦合器件（QCCD）平台，实现<strong>量子电路逻辑错误率相较原始物理电路下降11倍至800倍</strong>。首次完整验证了在运算过程中持续纠错的可行性。</p><h3 id="两项全新编码方案" tabindex="-1">两项全新编码方案 <a class="header-anchor" href="#两项全新编码方案" aria-label="Permalink to &quot;两项全新编码方案&quot;">​</a></h3><h4 id="碳码-c12码" tabindex="-1">碳码（C12码） <a class="header-anchor" href="#碳码-c12码" aria-label="Permalink to &quot;碳码（C12码）&quot;">​</a></h4><ul><li>来源于Knill经典容错协议，大幅重构</li><li>12物理比特→2逻辑比特，码距4</li><li>去掉复杂级联电路，物理比特和纠缠操作数量降低一个数量级</li><li>使用串行单比特隐形传态提取错误信息，定期刷新数据比特</li></ul><h4 id="超立方体色码-tessaract码" tabindex="-1">超立方体色码（Tessaract码） <a class="header-anchor" href="#超立方体色码-tessaract码" aria-label="Permalink to &quot;超立方体色码（Tessaract码）&quot;">​</a></h4><ul><li>16物理比特→4逻辑比特（主动舍去2个逻辑比特作规范比特）</li><li>实现&quot;测一次，纠错一次&quot;</li><li>规范比特可作临时运算资源，适应多逻辑比特并行运算</li></ul><h3 id="意义" tabindex="-1">意义 <a class="header-anchor" href="#意义" aria-label="Permalink to &quot;意义&quot;">​</a></h3><p>这是容错量子计算从理论走向硬件的关键一步。结合俞大鹏团队在超导量子模拟器上捕获精确量子临界态——量子计算正在两条路线（离子阱+超导）上同时突破。</p><hr><h2 id="_2026年6月-中国量子模拟捕获临界态" tabindex="-1">2026年6月：中国量子模拟捕获临界态 <a class="header-anchor" href="#_2026年6月-中国量子模拟捕获临界态" aria-label="Permalink to &quot;2026年6月：中国量子模拟捕获临界态&quot;">​</a></h2><p>俞大鹏团队（南方科技大学）在超导量子模拟器上成功捕获精确的量子临界态，为理解量子相变提供前所未有的实验平台。</p><hr><h2 id="_2026年6月-激光陀螺革命" tabindex="-1">2026年6月：激光陀螺革命 <a class="header-anchor" href="#_2026年6月-激光陀螺革命" aria-label="Permalink to &quot;2026年6月：激光陀螺革命&quot;">​</a></h2><h3 id="国防科技大学、陆军工程大学-《自然》-6月24日" tabindex="-1">国防科技大学、陆军工程大学（《自然》，6月24日） <a class="header-anchor" href="#国防科技大学、陆军工程大学-《自然》-6月24日" aria-label="Permalink to &quot;国防科技大学、陆军工程大学（《自然》，6月24日）&quot;">​</a></h3><p>研发出<strong>无需偏置元件的轻量化环形自偏置激光陀螺</strong>。核心突破是&quot;手性自发对称破缺&quot;——激光在腔内自发选择方向，从根源上根除闭锁效应。</p><table tabindex="0"><thead><tr><th>指标</th><th>传统</th><th>新型</th></tr></thead><tbody><tr><td>体积</td><td>砖头级</td><td>手掌级（缩小70%）</td></tr><tr><td>可靠性</td><td>基准</td><td>提高5倍</td></tr><tr><td>启动时间</td><td>10-30秒</td><td>0.5秒以内</td></tr><tr><td>功耗</td><td>基准</td><td>降低50%</td></tr><tr><td>精度</td><td>—</td><td>0.022°/小时（比地球自转角速度低近3个数量级）</td></tr></tbody></table><h3 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h3><ul><li><strong>军事</strong>：GPS拒止环境下自主导航，适配无人机群、无人潜航器、导弹末制导</li><li><strong>民用</strong>：隧道/地下车库厘米级定位，机器人亚毫米级运动控制</li><li><strong>消费级</strong>：可集成到手机/VR设备</li><li><strong>产线兼容</strong>：完全兼容传统产线，无需改造即可升级</li></ul><hr><h2 id="关键里程碑" tabindex="-1">关键里程碑 <a class="header-anchor" href="#关键里程碑" aria-label="Permalink to &quot;关键里程碑&quot;">​</a></h2><ul><li>2019年：Google Sycamore实现&quot;量子霸权&quot;</li><li>2023年：IBM 1121量子比特Condor处理器</li><li>2024年：Quantinuum实现56量子比特H2处理器</li><li>2025年：中国超导量子模拟器捕获量子临界态</li><li>2026年：微软×Quantinuum纠错800倍突破；激光陀螺手性自发对称破缺</li></ul>',26)])])}const m=a(o,[["render",l]]);export{q as __pageData,m as default};
